function killPid(pid) {
  if (!pid) return { pid, skipped: true };
  if (process.platform === 'win32') {
    const r = spawnSync('taskkill', ['/PID', String(pid), '/T', '/F'], { encoding: 'utf8' });
    return { pid, status: r.status, stdout: r.stdout, stderr: r.stderr, ok: r.status === 0 || /not found|没有找到/i.test(r.stderr || r.stdout || '') };
  }
