}

export async function run(input = {}) {
  const projectRoot = input.projectRoot || 'E:\\quant-framework';
  const stateFile = path.join(projectRoot, '.conexus', 'alphalab-runner', 'state.json');
  if (!fs.existsSync(stateFile)) return { ok: true, stopped: [], stateFile, message: 'No state file; nothing to stop.' };
  const state = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
  const stopped = [killPid(state.frontendPid), killPid(state.backendPid)];
  const ok = stopped.every(x => x.skipped || x.ok);
  const stoppedFile = stateFile.replace(/\.json$/, `.stopped.${Date.now()}.json`);
  fs.renameSync(stateFile, stoppedFile);
