        {t("common.unknownWidget")}: {componentId}
      </div>
    )
  }
  return (
    <PanelContext.Provider value={{ panelId: props.api.id, componentId, linkGroup, setLinkGroup }}>
      <Component />
    </PanelContext.Provider>
  )
}

